// The coach's settings (DBU-07, DBU-11): where learner messages are mailed (the Setting row, else the
// default placeholder) and the name learners see (empty: they see "your coach"). Staff only.
(async () => {
  try {
    const read = async (key) => {
      const rows = await Noodl.Records.query('Setting', { key: { equalTo: key } }, { limit: 2, plain: true });
      return rows[0] ? String(rows[0].value || '').trim() : '';
    };
    Outputs.defaultCoachEmail = 'coach@example.com';
    Outputs.coachEmail = (await read('coachEmail')) || 'coach@example.com';
    Outputs.coachName = await read('coachName');
    Outputs.done();
  } catch (e) {
    console.error('[dbu:coachSettings]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
